# Try the diagonal extension rule on demo 2
def apply_diagonal_extension(grid):
    """For each non-background cell, extend diagonal up-left"""
    bg = grid[0][0]  # Assuming uniform background
    result = [row[:] for row in grid]  # Copy

    # Find all non-background cells
    non_bg = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg:
                non_bg.append((r, c, grid[r][c]))

    # For each cell, extend up-left
    for r, c, v in non_bg:
        nr, nc = r + 1, c + 1  # Start point from which to extend up-left
        while nr - r <= 8 and nc - c <= 8:  # Go up-left (negative direction)
            if nr < 0 or nc < 0:
                break
            if result[nr][nc] != bg:
                break
            # Fill this cell with the value
            result[nr][nc] = v
            nr -= 1
            nc -= 1

    return result

