def apply_cross_fill(grid):
    """Fill horizontal and vertical lines between special cells"""
    bg = grid[0][0]
    result = [row[:] for row in grid]

    for r in range(len(grid)):
        # Find special cells in this row
        specials = []
        for c in range(len(grid[0])):
            if grid[r][c] != bg:
                specials.append((c, grid[r][c]))

        # Check if any pair on the row has background between them
        for i in range(len(specials)):
            for j in range(i+1, len(specials)):
                c1, v1 = specials[i]
                c2, v2 = specials[j]
                # Check if this is a same-value fill
                for c in range(c1 + 1, c2):
                    if result[r][c] == bg:
                        result[r][c] = v1

    for c in range(len(grid[0])):
        # Find special cells in this column
        specials = []
        for r in range(len(grid)):
            if grid[r][c] != bg:
                specials.append((r, grid[r][c]))

        # Fill between same-value pairs
        for i in range(len(specials)):
            for j in range(i+1, len(specials)):
                r1, v1 = specials[i]
                r2, v2 = specials[j]
                for r in range(r1 + 1, r2):
                    if result[r][c] == bg:
                        result[r][c] = v1

    return result

