def transform_grid(g):
    from collections import Counter
    H, W = len(g), len(g[0])
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]

    # Find all non-background positions by color with most common sum
    color_sums = {}  # color -> {sum -> count}
    for r in range(H):
        for c in range(W):
            val = g[r][c]
            if val != bg:
                s = r + c
                if val not in color_sums:
                    color_sums[val] = {}
                if s not in color_sums[val]:
                    color_sums[val][s] = 0
                color_sums[val][s] += 1

    # For each color, use the most common sum
    color_sums_final = {}
    for val, sums in color_sums.items():
        most_common_s = max(sums.keys(), key=lambda s: sums[s])
        color_sums_final[val] = most_common_s

    # Build result starting from background
    result = [[bg for _ in range(W)] for _ in range(H)]

    # Write colors in descending order (higher values overwrite lower)
    sorted_colors = sorted(color_sums_final.keys(), reverse=True)

    for color in sorted_colors:
        sample_sum = color_sums_final[color]

        for rr in range(H):
            cc = sample_sum - rr
            if 0 <= cc < W:
                result[rr][cc] = color

    return result

