def extend_runs(g):
    """Extends contiguous same-color runs along both diagonals"""
    from collections import Counter
    H, W = len(g), len(g[0])
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]
    out = [row[:] for row in g]

    for is_anti in [False, True]:  # diagonal (r-c) or anti-diagonal (r+c)
        lines = {}
        for r in range(H):
            for c in range(W):
                if g[r][c] != bg:
                    k = r - c if not is_anti else r + c
                    if k not in lines:
                        lines[k] = []
                    lines[k].append((r, c))

        # For each line, find contiguous same-color runs
        for pts in lines.values():
            if not pts:
                continue
            pts.sort()
            runs = []
            run = [pts[0]]
            for p in pts[1:]:
                if g[p[0]][p[1]] == g[run[-1][0]][run[-1][1]]:
                    run.append(p)
                else:
                    runs.append(run)
                    run = [p]
            runs.append(run)

            # Extend each run
            for run in runs:
                if len(run) < 2:
                    continue
                col = g[run[0][0]][run[0][1]]

                # Direction vectors
                if is_anti:
                    fwd = (1, -1)
                    bwd = (-1, 1)
                else:
                    fwd = (1, 1)
                    bwd = (-1, -1)

                for p in run:
                    rr, cc = p
                    # Forward
                    dir_pos = (r for r in range(len(run)))
                    for _ in dir_pos:
                        rr += fwd[0]
